<script setup>
import{ref,reactive,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{getWork,getReviews,getFavoriteStatus,toggleFavorite,saveReview}from'../api';import{ElMessage}from'element-plus'
const route=useRoute(),router=useRouter(),work=ref(null),reviews=ref([]),favorite=ref(false),user=JSON.parse(localStorage.getItem('craft-user')||'null'),review=reactive({rating:5,content:''})
async function load(){work.value=(await getWork(route.params.id)).data;reviews.value=(await getReviews(route.params.id)).data;if(user){try{favorite.value=(await getFavoriteStatus(route.params.id)).data.favorite}catch{}}}
async function toggle(){if(!user)return router.push('/login?redirect='+route.fullPath);favorite.value=(await toggleFavorite(route.params.id)).data.favorite}
async function submit(){if(!user)return router.push('/login?redirect='+route.fullPath);await saveReview(route.params.id,review);review.content='';reviews.value=(await getReviews(route.params.id)).data;ElMessage.success('评价已发布')}onMounted(load)
</script><template><div v-if="work"><section class="page-hero"><div class="container"><span>{{work.category}}</span><h1>{{work.title}}</h1><p>{{work.summary}}</p></div></section><section class="section"><div class="container" style="display:grid;grid-template-columns:1fr 1fr;gap:36px"><img :src="work.image" style="width:100%;height:500px;object-fit:cover;border-radius:24px"><div class="panel"><h2>{{work.title}}</h2><p>{{work.summary}}</p><p>创作者：{{work.creatorName}}</p><p>参考价格：<b>¥{{work.price}}</b>　制作周期：约{{work.leadDays}}天</p><button class="primary-btn" @click="$router.push('/custom')">以此为灵感发起定制</button> <button class="outline-btn" @click="toggle">{{favorite?'♥ 已收藏':'♡ 收藏作品'}}</button></div></div></section><section class="section"><div class="container"><h2>作品评价</h2><article v-for="r in reviews" :key="r.id" class="soft-card" style="margin:12px 0"><b>{{r.userName}}</b> · {{r.rating}} 星<p>{{r.content}}</p></article><div class="panel"><h3>发布评价</h3><el-rate v-model="review.rating"/><el-input v-model="review.content" type="textarea" :rows="4" placeholder="说说作品细节和体验"/><button class="primary-btn" style="margin-top:12px" @click="submit">提交评价</button></div></div></section></div></template>